int hammingWeight(uint32_t n) {
    int count = 0;
    while (n) {
        n &= n - 1;                                         // clears the lowest set bit
        ++count;
    }
    return count;
}

public int hammingWeight(int n) {
    int count = 0;
    while (n != 0) {
        n &= n - 1;                                     // clears the lowest set bit
        count++;
    }
    return count;
}
